class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        count = {}
        for i, n in enumerate(nums):
            count[n] = 1 + count.get(n, 0)

        buckets = {}
        for n, c in count.items():
            buckets[c] = buckets.get(c, []) + [n]

        res = []
        for c in range(len(nums), 0, -1):
            for n in buckets.get(c, []):
                res.append(n)
                if len(res) == k:
                    return res

        return res

